import re, json

def parse_judge_score(text, lo=1, hi=5):
    m = re.search(r"\{.*\}", text, re.DOTALL)   # first JSON object, ignore prose
    if not m:
        raise ValueError("judge returned no JSON object")
    try:
        data = json.loads(m.group(0))
    except json.JSONDecodeError as e:
        raise ValueError(f"unparseable judge JSON: {e}") from e
    if "score" not in data:
        raise ValueError("judge output missing 'score'")
    try:
        score = int(data["score"])
    except (TypeError, ValueError) as e:
        raise ValueError(f"'score' is not an integer: {data['score']!r}") from e
    if not lo <= score <= hi:
        raise ValueError(f"score {score} out of range [{lo}, {hi}]")
    reason = data.get("reason", "")
    return score, reason
